function classificarIdade(idade) {
  if (idade < 0) {
    return "Idade inválida";
  } else if (idade < 13) {
    return "Criança";
  } else if (idade < 18) {
    return "Adolescente";
  } else if (idade < 65) {
    return "Adulto";
  } else {
    return "Idoso";
  }
}

console.log(classificarIdade(30)); // "Adulto"
console.log(classificarIdade(-5)); // "Idade inválida"

let estado = "pendente";

if (estado === "pendente") {
  let mensagem = "A aguardar aprovação";
  console.log(mensagem);
}
// console.log(mensagem); // ReferenceError: mensagem não existe fora do bloco

let contador = 1;
if (true) {
  let contador = 100; // shadowing: nova variável, só válida dentro deste bloco
  console.log(contador); // 100
}
console.log(contador); // 1 - a variável externa não foi tocada

if (true) {
  var escapouDoBloco = "só var faz isto";
}
console.log(escapouDoBloco); // "só var faz isto" - var ignora o escopo de bloco

function descreverDia(diaSemana) {
  let tipo;
  switch (diaSemana) {
    case "sábado":
    case "domingo":
      tipo = "fim de semana";
      break;
    case "segunda":
    case "terça":
    case "quarta":
    case "quinta":
    case "sexta":
      tipo = "dia útil";
      break;
    default:
      tipo = "dia inválido";
  }
  return tipo;
}

console.log(descreverDia("sábado")); // "fim de semana"
console.log(descreverDia("quarta")); // "dia útil"

const codigoEstado = "2"; // por exemplo, veio de uma origem que só devolve strings

switch (codigoEstado) {
  case 1:
    console.log("Ativo");
    break;
  case 2:
    console.log("Inativo");
    break;
  default:
    console.log("Estado desconhecido"); // é isto que corre: "2" !== 2
}

// correção: converter para o mesmo tipo dos case
switch (Number(codigoEstado)) {
  case 1:
    console.log("Ativo");
    break;
  case 2:
    console.log("Inativo"); // agora corre corretamente
    break;
  default:
    console.log("Estado desconhecido");
}

// cadeia de if/else - fica longa quando há muitas alternativas exatas
function corDoEstado(estado) {
  if (estado === "novo") return "azul";
  else if (estado === "em progresso") return "amarelo";
  else if (estado === "concluído") return "verde";
  else if (estado === "cancelado") return "vermelho";
  else return "cinzento";
}

// o mesmo com switch - mais legível quando há muitas alternativas exatas
function corDoEstadoSwitch(estado) {
  switch (estado) {
    case "novo":
      return "azul";
    case "em progresso":
      return "amarelo";
    case "concluído":
      return "verde";
    case "cancelado":
      return "vermelho";
    default:
      return "cinzento";
  }
}

// com guard clauses: sem aninhamento, cada condição de erro sai logo
function calcularDesconto(cliente) {
  if (!cliente) {
    return 0;
  }
  if (!cliente.ativo) {
    return 0;
  }
  if (cliente.pontos < 100) {
    return 0;
  }
  return cliente.pontos * 0.01;
}

// a mesma lógica sem guard clauses, para comparação (mais aninhada)
function calcularDescontoAninhado(cliente) {
  let desconto = 0;
  if (cliente) {
    if (cliente.ativo) {
      if (cliente.pontos >= 100) {
        desconto = cliente.pontos * 0.01;
      }
    }
  }
  return desconto;
}

