exercises.statement:
Tem a seguinte função, que deveria devolver o nome de um nível de dificuldade a partir de um código, mas está sempre a devolver "Nível desconhecido":

function obterNomeNivel(codigo) {
  switch (codigo) {
    case 1:
      return "Fácil";
    case 2:
      return "Médio";
    case 3:
      return "Difícil";
    default:
      return "Nível desconhecido";
  }
}

A função é sempre chamada assim: obterNomeNivel(pedirCodigoAoUtilizador()), e pedirCodigoAoUtilizador() devolve sempre uma string, por exemplo "1", "2" ou "3", nunca um número. Explique, com base na forma como o switch compara valores, porque é que a função falha sempre, e reescreva-a para funcionar corretamente independentemente de o código chegar como string ou como número.

exercises.solution_code:
function obterNomeNivel(codigo) {
  switch (Number(codigo)) {
    case 1:
      return "Fácil";
    case 2:
      return "Médio";
    case 3:
      return "Difícil";
    default:
      return "Nível desconhecido";
  }
}

console.log(obterNomeNivel("2")); // "Médio"
console.log(obterNomeNivel(3));   // "Difícil"

exercises.statement:
Tem a seguinte função de validação de registo, com if aninhados dentro de else:

function validarRegisto(idade, email, aceitouTermos) {
  let resultado;
  if (idade !== undefined) {
    if (idade >= 18) {
      if (email && email.includes("@")) {
        if (aceitouTermos) {
          resultado = "Registo válido";
        } else {
          resultado = "Erro: tem de aceitar os termos";
        }
      } else {
        resultado = "Erro: email inválido";
      }
    } else {
      resultado = "Erro: idade mínima de 18 anos";
    }
  } else {
    resultado = "Erro: idade em falta";
  }
  return resultado;
}

Reescreva esta função usando guard clauses (saídas antecipadas com return), eliminando todo o aninhamento e mantendo exatamente as mesmas mensagens e a mesma ordem de validação.

