function validarRegisto(idade, email, aceitouTermos) {
  if (idade === undefined) {
    return "Erro: idade em falta";
  }
  if (idade < 18) {
    return "Erro: idade mínima de 18 anos";
  }
  if (!email || !email.includes("@")) {
    return "Erro: email inválido";
  }
  if (!aceitouTermos) {
    return "Erro: tem de aceitar os termos";
  }
  return "Registo válido";
}

console.log(validarRegisto(undefined, "a@b.pt", true)); // "Erro: idade em falta"
console.log(validarRegisto(16, "a@b.pt", true));        // "Erro: idade mínima de 18 anos"
console.log(validarRegisto(20, "semarroba", true));     // "Erro: email inválido"
console.log(validarRegisto(20, "a@b.pt", false));        // "Erro: tem de aceitar os termos"
console.log(validarRegisto(20, "a@b.pt", true));         // "Registo válido"
